/* Generated by tools/build-news.cjs from tools/editorial/{lang}.json — edit the JSON, not this file. */
window.ET_NEWS = {"es":{"meta":{"title":"Noticias · Diario EMPERIO TISS","description":"Diario de EMPERIO TISS: novedades del catálogo, notas de producto y claves de origen para compradores profesionales de productos del mar, frutas y hortalizas."},"hero":{"kicker":"DIARIO EMPERIO TISS","edition":"Edición de octubre · 2026","place":"Desde Madrid","h1":"Criterio<br><em>de mercado.</em>","lead":"Lo que cambia en nuestra selección y cómo leerlo: catálogo, producto y origen, contados para quien compra.","cta":"Leer la edición"},"ui":{"filters":{"all":"Todo","catalogue":"Catálogo","product":"Producto","origin":"Origen","company":"Empresa"},"cover":"Portada","inEdition":"En esta edición","indexTitle":"Las notas<br><em>de la edición.</em>","read":"Leer el artículo","minutes":"min de lectura","close":"Cerrar","date":"Octubre 2026","next":"Siguiente artículo"},"articles":[{"id":"fruta-nueve-familias","tag":"catalogue","image":"fruits","title":"La fruta, en nueve familias.","dek":"Treinta y tres referencias ordenadas como se compran: por familia, origen y campaña.","body":["El catálogo de frutas de EMPERIO TISS reúne ya 33 referencias, organizadas en nueve familias: cítricos, fruta de hueso, frutos rojos, uva de mesa, fruta de pepita, fruta mediterránea de temporada, tropicales, melones y dátiles.","Cada familia agrupa productos que comparten ritmo de campaña y forma de especificarse. Quien compra cítricos habla de variedad, calibre y destino; quien compra frutos rojos, de formato y continuidad. Ordenar el catálogo así hace la conversación más corta y más precisa.","Entre las incorporaciones recientes figuran el higo, el higo chumbo y el kaki, junto a tropicales como el lichi, el maracuyá o la papaya. Todas cuentan con fotografía propia y con una referencia permanente de cuatro dígitos.","La disponibilidad se confirma siempre por campaña y programa de suministro: el catálogo describe lo que seleccionamos, no existencias inmediatas."],"link":{"label":"Ver el catálogo de frutas","href":"products/fruits/"}},{"id":"hortalizas-calendario","tag":"catalogue","image":"vegetables","title":"Hortalizas: el calendario, a la vista.","dek":"Doce referencias con su disponibilidad mes a mes en España y en Marruecos.","body":["Cada hortaliza del catálogo muestra ahora un calendario anual con dos orígenes, España y Marruecos, y tres niveles de disponibilidad: alta, media y limitada.","La lectura es inmediata. Cuando la campaña española del tomate se reduce a final de año, la de Marruecos alcanza su nivel alto, de noviembre a abril. Brócoli y coliflor concentran su disponibilidad alta en los meses fríos, mientras que la patata y el ajo de España la alcanzan en verano.","Son datos orientativos, sujetos a campaña y programa de suministro, pensados para planificar las compras con antelación. El almanaque completo, mes a mes, está en la página de Temporada."],"link":{"label":"Abrir el almanaque de temporada","href":"products/seasonal/"}},{"id":"congelado-a-bordo","tag":"product","image":"shellfish","title":"Congelado a bordo: el origen, detenido.","dek":"Por qué cuatro de nuestros mariscos y todos los cefalópodos se ofrecen congelados.","body":["En nuestro catálogo, el moruno, la cigala, la gamba blanca y el langostino tigre se presentan congelados a bordo. El mejillón, en cambio, se ofrece fresco.","La congelación a bordo se realiza en el propio buque, poco después de la captura. Para quien compra, significa un producto estable que puede planificarse con más margen que el fresco.","Los cefalópodos —pulpo, calamar, puntillas y sepia— se ofrecen congelados, con especificación por especie, origen, calibre y presentación.","Fresco y congelado no compiten: responden a necesidades distintas de cocina, distribución y rotación. Elegir bien empieza por saber para qué se compra."],"link":{"label":"Ver mariscos","href":"products/seafood/shellfish/"}},{"id":"zona-fao","tag":"origin","image":"fish","title":"Leer una zona FAO.","dek":"El número que acompaña a cada pescado indica dónde se capturó. Así se interpreta.","body":["La FAO divide los mares y océanos en grandes áreas de pesca numeradas. En la Unión Europea, la zona de captura forma parte de la información obligatoria de los productos de la pesca: es la forma más precisa de expresar su origen.","En nuestro catálogo aparecen tres áreas principales: la zona 27, Atlántico Nordeste; la zona 34, Atlántico Centro-Este; y la zona 37, Mediterráneo y mar Negro, que a su vez se divide en subzonas como la 37.1.3 o la 37.2.","Por eso indicamos para cada referencia el país de origen y la zona FAO. Es la información que permite comparar, documentar y comercializar con transparencia."],"link":{"label":"Ver pescados","href":"products/seafood/fish/"}},{"id":"calibre","tag":"product","image":"cephalopods","title":"El calibre no se mide igual en todas partes.","dek":"Peso por pieza, piezas por kilo o diámetro: cada familia tiene su propia escala.","body":["Hablar de calibre sin precisar la escala es una fuente frecuente de malentendidos. En pescado suele expresarse en peso por pieza; en marisco, en piezas por kilo; en fruta, en diámetro o en número de piezas por envase.","Por eso cada ficha de nuestro catálogo trata el calibre según la familia del producto y, cuando corresponde, según la especificación del comprador.","Una buena especificación —calibre, presentación, formato y envase— es la mitad de una buena compra."],"link":{"label":"Ver productos del mar","href":"products/seafood/"}},{"id":"referencia-permanente","tag":"company","image":"news","title":"Una referencia permanente para cada producto.","dek":"Cuatro dígitos que no cambian: así se identifica cada producto en consultas, pedidos y ofertas.","body":["Cada producto del catálogo —del mar, fruta u hortaliza— tiene una referencia propia de cuatro dígitos, visible en su ficha.","La referencia es permanente: no depende del idioma, del orden del catálogo ni de la campaña. Permite citar un producto sin ambigüedad en una consulta, un pedido o una oferta, en cualquiera de nuestros cinco idiomas."],"link":{"label":"Ver todos los productos","href":"products/"}},{"id":"cinco-idiomas","tag":"company","image":"season","title":"Un mismo catálogo, cinco idiomas.","dek":"Español, inglés, francés, italiano y árabe comparten selección, diseño y referencias.","body":["El catálogo de EMPERIO TISS se presenta en español, inglés, francés, italiano y árabe, con la misma selección de productos y el mismo diseño de ficha.","Los nombres comerciales se adaptan a cada idioma; el nombre científico, el origen, la zona FAO y la referencia permanecen idénticos. Así, compradores de mercados distintos hablan exactamente del mismo producto."],"link":{"label":"Hablar con EMPERIO TISS","href":"contact/"}}],"quote":{"text":"Seleccionar es decidir con criterio: qué producto, de qué origen y en qué momento.","cite":"EMPERIO TISS"},"letter":{"kicker":"LA CARTA","h2":"Lo esencial,<br><em>en su correo.</em>","text":"Novedades del catálogo, notas de campaña y lecturas de producto. Sin ruido: solo lo relevante para quien compra."}},"en":{"meta":{"title":"News · The EMPERIO TISS Journal","description":"The EMPERIO TISS Journal: catalogue news, product notes and keys to origin for professional buyers of seafood, fruit and vegetables."},"hero":{"kicker":"THE EMPERIO TISS JOURNAL","edition":"October edition · 2026","place":"From Madrid","h1":"A sense<br><em>of the market.</em>","lead":"What changes in our selection and how to read it: catalogue, product and origin, told for those who buy.","cta":"Read the edition"},"ui":{"filters":{"all":"All","catalogue":"Catalogue","product":"Product","origin":"Origin","company":"Company"},"cover":"Front page","inEdition":"In this edition","indexTitle":"The notes<br><em>in this edition.</em>","read":"Read the article","minutes":"min read","close":"Close","date":"October 2026","next":"Next article"},"articles":[{"id":"fruta-nueve-familias","tag":"catalogue","image":"fruits","title":"Fruit, in nine families.","dek":"Thirty-three references, arranged the way they are bought: by family, origin and campaign.","body":["The EMPERIO TISS fruit catalogue now brings together 33 references, organised into nine families: citrus, stone fruit, berries, table grapes, pome fruit, seasonal Mediterranean fruit, tropical fruit, melons and dates.","Each family groups products that share a campaign rhythm and a way of being specified. Those who buy citrus talk about variety, calibre and destination; those who buy berries, about format and continuity. Arranging the catalogue this way makes the conversation shorter and more precise.","Recent additions include fig, prickly pear and persimmon, alongside tropical fruits such as lychee, passion fruit and papaya. All have their own photography and a permanent four-digit reference.","Availability is always confirmed by campaign and supply programme: the catalogue describes what we select, not immediate stock."],"link":{"label":"View the fruit catalogue","href":"products/fruits/"}},{"id":"hortalizas-calendario","tag":"catalogue","image":"vegetables","title":"Vegetables: the calendar at a glance.","dek":"Twelve references with their month-by-month availability in Spain and Morocco.","body":["Every vegetable in the catalogue now shows an annual calendar with two origins, Spain and Morocco, and three levels of availability: high, medium and limited.","It reads at once. When the Spanish tomato campaign winds down at the end of the year, Morocco’s reaches its high level, from November to April. Broccoli and cauliflower concentrate their high availability in the colder months, while potatoes and garlic from Spain reach it in summer.","These figures are indicative, subject to season and supply programme, and intended for planning purchases in advance. The full almanac, month by month, is on the Seasonal page."],"link":{"label":"Open the seasonal almanac","href":"products/seasonal/"}},{"id":"congelado-a-bordo","tag":"product","image":"shellfish","title":"Frozen at sea: the origin, held still.","dek":"Why four of our shellfish and all our cephalopods are offered frozen.","body":["In our catalogue, blue and red shrimp, Norway lobster, deep-water rose shrimp and black tiger prawn are presented frozen at sea. Mussels, by contrast, are offered fresh.","Freezing at sea takes place on the vessel itself, shortly after the catch. For the buyer, it means a stable product that can be planned with more leeway than fresh.","Cephalopods – octopus, squid, baby squid and cuttlefish – are offered frozen, specified by species, origin, calibre and presentation.","Fresh and frozen do not compete: they meet different needs in the kitchen, in distribution and in stock rotation. Choosing well begins with knowing what you are buying for."],"link":{"label":"View shellfish","href":"products/seafood/shellfish/"}},{"id":"zona-fao","tag":"origin","image":"fish","title":"Reading an FAO area.","dek":"The number that accompanies each fish tells you where it was caught. Here is how to read it.","body":["The FAO divides the seas and oceans into large, numbered fishing areas. In the European Union, the catch area is part of the mandatory information for fishery products: it is the most precise way of stating their origin.","Three main areas appear in our catalogue: area 27, Northeast Atlantic; area 34, Eastern Central Atlantic; and area 37, Mediterranean and Black Sea, which is in turn divided into subareas such as 37.1.3 or 37.2.","That is why we state the country of origin and the FAO area for every reference. It is the information that makes it possible to compare, document and market with transparency."],"link":{"label":"View fish","href":"products/seafood/fish/"}},{"id":"calibre","tag":"product","image":"cephalopods","title":"Calibre is not measured the same way everywhere.","dek":"Weight per piece, pieces per kilo or diameter: each family has its own scale.","body":["Talking about calibre without specifying the scale is a frequent source of misunderstanding. For fish it is usually expressed as weight per piece; for shellfish, as pieces per kilo; for fruit, as diameter or number of pieces per pack.","That is why each product sheet in our catalogue treats calibre according to the product family and, where appropriate, according to the buyer’s specification.","A good specification – calibre, presentation, format and packaging – is half of a good purchase."],"link":{"label":"View seafood","href":"products/seafood/"}},{"id":"referencia-permanente","tag":"company","image":"news","title":"A permanent reference for every product.","dek":"Four digits that never change: this is how each product is identified in enquiries, orders and offers.","body":["Every product in the catalogue – seafood, fruit or vegetable – has its own four-digit reference, shown on its product sheet.","The reference is permanent: it does not depend on the language, the order of the catalogue or the campaign. It allows a product to be cited without ambiguity in an enquiry, an order or an offer, in any of our five languages."],"link":{"label":"View all products","href":"products/"}},{"id":"cinco-idiomas","tag":"company","image":"season","title":"One catalogue, five languages.","dek":"Spanish, English, French, Italian and Arabic share the same selection, design and references.","body":["The EMPERIO TISS catalogue is presented in Spanish, English, French, Italian and Arabic, with the same product selection and the same product sheet design.","Trade names are adapted to each language; the scientific name, origin, FAO area and reference remain identical. In this way, buyers in different markets are talking about exactly the same product."],"link":{"label":"Talk to EMPERIO TISS","href":"contact/"}}],"quote":{"text":"To select is to decide with judgement: which product, from which origin and at what moment.","cite":"EMPERIO TISS"},"letter":{"kicker":"THE LETTER","h2":"The essentials,<br><em>in your inbox.</em>","text":"Catalogue news, campaign notes and product readings. No noise: only what matters to those who buy."}},"fr":{"meta":{"title":"Actualités · Le Journal EMPERIO TISS","description":"Le Journal EMPERIO TISS : nouveautés du catalogue, notes produit et repères d’origine pour les acheteurs professionnels de produits de la mer, de fruits et de légumes."},"hero":{"kicker":"LE JOURNAL EMPERIO TISS","edition":"Édition d’octobre · 2026","place":"Depuis Madrid","h1":"Le sens<br><em>du marché.</em>","lead":"Ce qui change dans notre sélection et comment le lire : catalogue, produit et origine, racontés pour ceux qui achètent.","cta":"Lire l’édition"},"ui":{"filters":{"all":"Tout","catalogue":"Catalogue","product":"Produit","origin":"Origine","company":"Entreprise"},"cover":"À la une","inEdition":"Dans cette édition","indexTitle":"Les notes<br><em>de l’édition.</em>","read":"Lire l’article","minutes":"min de lecture","close":"Fermer","date":"Octobre 2026","next":"Article suivant"},"articles":[{"id":"fruta-nueve-familias","tag":"catalogue","image":"fruits","title":"Les fruits, en neuf familles.","dek":"Trente-trois références classées comme elles s’achètent : par famille, origine et campagne.","body":["Le catalogue de fruits d’EMPERIO TISS réunit désormais 33 références, organisées en neuf familles : agrumes, fruits à noyau, fruits rouges, raisin de table, fruits à pépins, fruits méditerranéens de saison, fruits tropicaux, melons et dattes.","Chaque famille regroupe des produits qui partagent un rythme de campagne et une manière d’être spécifiés. Qui achète des agrumes parle de variété, de calibre et de destination ; qui achète des fruits rouges, de format et de continuité. Organiser ainsi le catalogue rend la conversation plus courte et plus précise.","Parmi les ajouts récents figurent la figue, la figue de Barbarie et le kaki, aux côtés de fruits tropicaux comme le litchi, le fruit de la passion ou la papaye. Tous disposent de leur propre photographie et d’une référence permanente à quatre chiffres.","La disponibilité est toujours confirmée par campagne et programme d’approvisionnement : le catalogue décrit ce que nous sélectionnons, non des stocks immédiats."],"link":{"label":"Voir le catalogue de fruits","href":"products/fruits/"}},{"id":"hortalizas-calendario","tag":"catalogue","image":"vegetables","title":"Légumes : le calendrier, en un coup d’œil.","dek":"Douze références et leur disponibilité mois par mois en Espagne et au Maroc.","body":["Chaque légume du catalogue affiche désormais un calendrier annuel avec deux origines, l’Espagne et le Maroc, et trois niveaux de disponibilité : forte, moyenne et limitée.","La lecture est immédiate. Lorsque la campagne espagnole de la tomate se réduit en fin d’année, celle du Maroc atteint son niveau élevé, de novembre à avril. Le brocoli et le chou-fleur concentrent leur forte disponibilité pendant les mois froids, tandis que la pomme de terre et l’ail d’Espagne l’atteignent en été.","Ce sont des données indicatives, selon campagne et programme d’approvisionnement, conçues pour planifier les achats à l’avance. L’almanach complet, mois par mois, se trouve sur la page Saison."],"link":{"label":"Ouvrir l’almanach de saison","href":"products/seasonal/"}},{"id":"congelado-a-bordo","tag":"product","image":"shellfish","title":"Congelé à bord : l’origine, suspendue.","dek":"Pourquoi quatre de nos fruits de mer et tous nos céphalopodes sont proposés congelés.","body":["Dans notre catalogue, la crevette rouge, la langoustine, la crevette rose et la crevette tigrée sont présentées congelées à bord. La moule, en revanche, est proposée fraîche.","La congélation à bord est réalisée sur le navire lui-même, peu après la capture. Pour l’acheteur, cela signifie un produit stable, que l’on peut planifier avec plus de marge que le frais.","Les céphalopodes — poulpe, calmar, petits calamars et seiche — sont proposés congelés, avec une spécification par espèce, origine, calibre et présentation.","Le frais et le congelé ne s’opposent pas : ils répondent à des besoins différents de cuisine, de distribution et de rotation. Bien choisir commence par savoir pourquoi l’on achète."],"link":{"label":"Voir les fruits de mer","href":"products/seafood/shellfish/"}},{"id":"zona-fao","tag":"origin","image":"fish","title":"Lire une zone FAO.","dek":"Le numéro qui accompagne chaque poisson indique où il a été pêché. Voici comment l’interpréter.","body":["La FAO divise les mers et les océans en grandes zones de pêche numérotées. Dans l’Union européenne, la zone de capture fait partie des informations obligatoires des produits de la pêche : c’est la manière la plus précise d’en exprimer l’origine.","Trois zones principales apparaissent dans notre catalogue : la zone 27, Atlantique Nord-Est ; la zone 34, Atlantique Centre-Est ; et la zone 37, Méditerranée et mer Noire, elle-même divisée en sous-zones comme la 37.1.3 ou la 37.2.","C’est pourquoi nous indiquons pour chaque référence le pays d’origine et la zone FAO. C’est l’information qui permet de comparer, de documenter et de commercialiser en toute transparence."],"link":{"label":"Voir les poissons","href":"products/seafood/fish/"}},{"id":"calibre","tag":"product","image":"cephalopods","title":"Le calibre ne se mesure pas partout de la même façon.","dek":"Poids par pièce, pièces par kilo ou diamètre : chaque famille a sa propre échelle.","body":["Parler de calibre sans préciser l’échelle est une source fréquente de malentendus. Pour le poisson, il s’exprime généralement en poids par pièce ; pour les fruits de mer, en pièces par kilo ; pour les fruits, en diamètre ou en nombre de pièces par colis.","C’est pourquoi chaque fiche de notre catalogue traite le calibre selon la famille du produit et, le cas échéant, selon la spécification de l’acheteur.","Une bonne spécification — calibre, présentation, format et conditionnement — est la moitié d’un bon achat."],"link":{"label":"Voir les produits de la mer","href":"products/seafood/"}},{"id":"referencia-permanente","tag":"company","image":"news","title":"Une référence permanente pour chaque produit.","dek":"Quatre chiffres qui ne changent pas : c’est ainsi que chaque produit est identifié dans les demandes, les commandes et les offres.","body":["Chaque produit du catalogue — de la mer, fruit ou légume — possède sa propre référence à quatre chiffres, visible sur sa fiche.","La référence est permanente : elle ne dépend ni de la langue, ni de l’ordre du catalogue, ni de la campagne. Elle permet de citer un produit sans ambiguïté dans une demande, une commande ou une offre, dans chacune de nos cinq langues."],"link":{"label":"Voir tous les produits","href":"products/"}},{"id":"cinco-idiomas","tag":"company","image":"season","title":"Un même catalogue, cinq langues.","dek":"Espagnol, anglais, français, italien et arabe partagent la même sélection, le même design et les mêmes références.","body":["Le catalogue d’EMPERIO TISS est présenté en espagnol, en anglais, en français, en italien et en arabe, avec la même sélection de produits et le même design de fiche.","Les noms commerciaux s’adaptent à chaque langue ; le nom scientifique, l’origine, la zone FAO et la référence restent identiques. Ainsi, des acheteurs de marchés différents parlent exactement du même produit."],"link":{"label":"Échanger avec EMPERIO TISS","href":"contact/"}}],"quote":{"text":"Sélectionner, c’est décider avec discernement : quel produit, de quelle origine et à quel moment.","cite":"EMPERIO TISS"},"letter":{"kicker":"LA LETTRE","h2":"L’essentiel,<br><em>dans votre boîte mail.</em>","text":"Nouveautés du catalogue, notes de campagne et lectures produit. Sans bruit : seulement ce qui compte pour ceux qui achètent."}},"it":{"meta":{"title":"Notizie · Il Giornale EMPERIO TISS","description":"Il Giornale EMPERIO TISS: novità del catalogo, note di prodotto e chiavi d’origine per acquirenti professionali di prodotti del mare, frutta e ortaggi."},"hero":{"kicker":"IL GIORNALE EMPERIO TISS","edition":"Edizione di ottobre · 2026","place":"Da Madrid","h1":"Criterio<br><em>di mercato.</em>","lead":"Ciò che cambia nella nostra selezione e come leggerlo: catalogo, prodotto e origine, raccontati per chi acquista.","cta":"Leggi l’edizione"},"ui":{"filters":{"all":"Tutto","catalogue":"Catalogo","product":"Prodotto","origin":"Origine","company":"Azienda"},"cover":"Prima pagina","inEdition":"In questa edizione","indexTitle":"Le note<br><em>dell’edizione.</em>","read":"Leggi l’articolo","minutes":"min di lettura","close":"Chiudi","date":"Ottobre 2026","next":"Articolo successivo"},"articles":[{"id":"fruta-nueve-familias","tag":"catalogue","image":"fruits","title":"La frutta, in nove famiglie.","dek":"Trentatré referenze ordinate come si acquistano: per famiglia, origine e campagna.","body":["Il catalogo della frutta di EMPERIO TISS riunisce ormai 33 referenze, organizzate in nove famiglie: agrumi, frutta a nocciolo, frutti di bosco, uva da tavola, pomacee, frutta mediterranea di stagione, frutta tropicale, meloni e datteri.","Ogni famiglia raggruppa prodotti che condividono il ritmo di campagna e il modo di essere specificati. Chi acquista agrumi parla di varietà, calibro e destinazione; chi acquista frutti di bosco, di formato e continuità. Ordinare così il catalogo rende la conversazione più breve e più precisa.","Tra le aggiunte recenti figurano il fico, il fico d’India e il cachi, accanto a frutti tropicali come il litchi, il frutto della passione o la papaya. Tutti dispongono di una fotografia propria e di una referenza permanente di quattro cifre.","La disponibilità si conferma sempre per campagna e programma di fornitura: il catalogo descrive ciò che selezioniamo, non giacenze immediate."],"link":{"label":"Scopri il catalogo della frutta","href":"products/fruits/"}},{"id":"hortalizas-calendario","tag":"catalogue","image":"vegetables","title":"Ortaggi: il calendario, a colpo d’occhio.","dek":"Dodici referenze con la loro disponibilità mese per mese in Spagna e in Marocco.","body":["Ogni ortaggio del catalogo mostra ora un calendario annuale con due origini, Spagna e Marocco, e tre livelli di disponibilità: alta, media e limitata.","La lettura è immediata. Quando la campagna spagnola del pomodoro si riduce a fine anno, quella del Marocco raggiunge il suo livello alto, da novembre ad aprile. Broccoli e cavolfiore concentrano la loro disponibilità alta nei mesi freddi, mentre la patata e l’aglio di Spagna la raggiungono in estate.","Sono dati indicativi, secondo campagna e programma di fornitura, pensati per pianificare gli acquisti con anticipo. L’almanacco completo, mese per mese, si trova nella pagina Stagionale."],"link":{"label":"Apri l’almanacco stagionale","href":"products/seasonal/"}},{"id":"congelado-a-bordo","tag":"product","image":"shellfish","title":"Congelato a bordo: l’origine, fermata nel tempo.","dek":"Perché quattro dei nostri frutti di mare e tutti i cefalopodi sono offerti congelati.","body":["Nel nostro catalogo, il gambero rosso, lo scampo, il gambero rosa e il gambero tigre sono presentati congelati a bordo. La cozza, invece, è offerta fresca.","La congelazione a bordo avviene sulla nave stessa, poco dopo la cattura. Per chi acquista, significa un prodotto stabile, che si può pianificare con più margine rispetto al fresco.","I cefalopodi – polpo, calamaro, totanetti e seppia – sono offerti congelati, con specifica per specie, origine, calibro e presentazione.","Fresco e congelato non sono in competizione: rispondono a esigenze diverse di cucina, distribuzione e rotazione. Scegliere bene comincia dal sapere per che cosa si acquista."],"link":{"label":"Vedi i crostacei","href":"products/seafood/shellfish/"}},{"id":"zona-fao","tag":"origin","image":"fish","title":"Leggere una zona FAO.","dek":"Il numero che accompagna ogni pesce indica dove è stato catturato. Ecco come si interpreta.","body":["La FAO divide mari e oceani in grandi aree di pesca numerate. Nell’Unione europea, la zona di cattura fa parte delle informazioni obbligatorie dei prodotti della pesca: è il modo più preciso di esprimerne l’origine.","Nel nostro catalogo compaiono tre aree principali: la zona 27, Atlantico nord-orientale; la zona 34, Atlantico centro-orientale; e la zona 37, Mediterraneo e Mar Nero, a sua volta suddivisa in sottozone come la 37.1.3 o la 37.2.","Per questo indichiamo per ogni referenza il paese d’origine e la zona FAO. È l’informazione che permette di confrontare, documentare e commercializzare con trasparenza."],"link":{"label":"Vedi il pesce","href":"products/seafood/fish/"}},{"id":"calibre","tag":"product","image":"cephalopods","title":"Il calibro non si misura ovunque allo stesso modo.","dek":"Peso per pezzo, pezzi per chilo o diametro: ogni famiglia ha la propria scala.","body":["Parlare di calibro senza precisarne la scala è una fonte frequente di malintesi. Per il pesce si esprime di solito in peso per pezzo; per i frutti di mare, in pezzi per chilo; per la frutta, in diametro o in numero di pezzi per collo.","Per questo ogni scheda del nostro catalogo tratta il calibro secondo la famiglia del prodotto e, quando opportuno, secondo la specifica dell’acquirente.","Una buona specifica – calibro, presentazione, formato e imballaggio – è metà di un buon acquisto."],"link":{"label":"Vedi i prodotti del mare","href":"products/seafood/"}},{"id":"referencia-permanente","tag":"company","image":"news","title":"Una referenza permanente per ogni prodotto.","dek":"Quattro cifre che non cambiano: così si identifica ogni prodotto in richieste, ordini e offerte.","body":["Ogni prodotto del catalogo – del mare, frutta od ortaggio – ha una propria referenza di quattro cifre, visibile nella sua scheda.","La referenza è permanente: non dipende dalla lingua, dall’ordine del catalogo né dalla campagna. Permette di citare un prodotto senza ambiguità in una richiesta, un ordine o un’offerta, in ciascuna delle nostre cinque lingue."],"link":{"label":"Vedi tutti i prodotti","href":"products/"}},{"id":"cinco-idiomas","tag":"company","image":"season","title":"Uno stesso catalogo, cinque lingue.","dek":"Spagnolo, inglese, francese, italiano e arabo condividono selezione, design e referenze.","body":["Il catalogo di EMPERIO TISS è presentato in spagnolo, inglese, francese, italiano e arabo, con la stessa selezione di prodotti e lo stesso design della scheda.","I nomi commerciali si adattano a ogni lingua; il nome scientifico, l’origine, la zona FAO e la referenza restano identici. Così, acquirenti di mercati diversi parlano esattamente dello stesso prodotto."],"link":{"label":"Parla con EMPERIO TISS","href":"contact/"}}],"quote":{"text":"Selezionare è decidere con criterio: quale prodotto, da quale origine e in quale momento.","cite":"EMPERIO TISS"},"letter":{"kicker":"LA LETTERA","h2":"L’essenziale,<br><em>nella sua casella di posta.</em>","text":"Novità del catalogo, note di campagna e letture di prodotto. Senza rumore: solo ciò che conta per chi acquista."}},"ar":{"meta":{"title":"الأخبار · مجلة EMPERIO TISS","description":"مجلة EMPERIO TISS: مستجدات الكتالوج، وملاحظات حول المنتجات، ومفاتيح لفهم المنشأ، للمشترين المحترفين للمأكولات البحرية والفواكه والخضروات."},"hero":{"kicker":"مجلة EMPERIO TISS","edition":"عدد أكتوبر · 2026","place":"من مدريد","h1":"بصيرة<br><em>السوق.</em>","lead":"ما يتغير في انتقائنا وكيف يُقرأ: الكتالوج والمنتج والمنشأ، نرويها لمن يشتري.","cta":"قراءة العدد"},"ui":{"filters":{"all":"الكل","catalogue":"الكتالوج","product":"المنتج","origin":"المنشأ","company":"الشركة"},"cover":"الصفحة الأولى","inEdition":"في هذا العدد","indexTitle":"موضوعات<br><em>هذا العدد.</em>","read":"قراءة المقال","minutes":"دقائق للقراءة","close":"إغلاق","date":"أكتوبر 2026","next":"المقال التالي"},"articles":[{"id":"fruta-nueve-familias","tag":"catalogue","image":"fruits","title":"الفاكهة في تسع فئات.","dek":"ثلاثة وثلاثون مرجعًا مرتّبة كما تُشترى: حسب الفئة والمنشأ والموسم.","body":["يضم كتالوج الفواكه لدى EMPERIO TISS الآن 33 مرجعًا موزعة على تسع فئات: الحمضيات، والفواكه ذات النواة، والتوتيات، وعنب المائدة، والتفاحيات، والفواكه المتوسطية الموسمية، والفواكه الاستوائية، والشمام، والتمور.","تجمع كل فئة منتجات تتشارك إيقاع الموسم وطريقة تحديد المواصفات. فمن يشتري الحمضيات يتحدث عن الصنف والعيار والوجهة، ومن يشتري التوتيات يتحدث عن الشكل والاستمرارية. وترتيب الكتالوج على هذا النحو يجعل الحوار أقصر وأدق.","ومن أحدث الإضافات التين والتين الشوكي والكاكا، إلى جانب فواكه استوائية مثل الليتشي وفاكهة الباشن والبابايا. ولكل منها صورها الخاصة ومرجع دائم من أربعة أرقام.","يُؤكَّد التوفر دائمًا حسب الموسم وبرنامج التوريد: فالكتالوج يصف ما ننتقيه، لا مخزونًا فوريًا."],"link":{"label":"عرض كتالوج الفواكه","href":"products/fruits/"}},{"id":"hortalizas-calendario","tag":"catalogue","image":"vegetables","title":"الخضروات: التقويم بنظرة واحدة.","dek":"اثنا عشر مرجعًا بتوفرها شهرًا بشهر في إسبانيا والمغرب.","body":["يعرض كل نوع من الخضروات في الكتالوج الآن تقويمًا سنويًا بمنشأين، إسبانيا والمغرب، وثلاثة مستويات للتوفر: مرتفع ومتوسط ومحدود.","القراءة فورية. فحين يتراجع موسم الطماطم الإسبانية في نهاية العام، يبلغ موسم المغرب مستواه المرتفع، من نوفمبر إلى أبريل. ويتركز التوفر المرتفع للبروكلي والقرنبيط في الأشهر الباردة، بينما تبلغه البطاطس والثوم من إسبانيا في الصيف.","هذه بيانات إرشادية، تخضع للموسم ولبرنامج التوريد، ووُضعت للتخطيط المسبق للمشتريات. والتقويم الكامل، شهرًا بشهر، متاح في صفحة المنتجات الموسمية."],"link":{"label":"فتح تقويم المواسم","href":"products/seasonal/"}},{"id":"congelado-a-bordo","tag":"product","image":"shellfish","title":"مجمد على متن السفينة: المنشأ وقد توقّف عنده الزمن.","dek":"لماذا نقدّم أربعة من قشرياتنا وجميع رأسيات الأرجل مجمدة.","body":["في كتالوجنا، يُقدَّم الروبيان الأحمر واللانغوستين والجمبري الأبيض والروبيان النمر مجمدةً على متن السفينة. أما بلح البحر فيُقدَّم طازجًا.","يجري التجميد على متن السفينة نفسها، بعد وقت قصير من الصيد. ويعني ذلك للمشتري منتجًا مستقرًا يمكن التخطيط له بهامش أوسع مما يتيحه الطازج.","أما رأسيات الأرجل — الأخطبوط والحبار والحبار الصغير والسيبيا — فتُقدَّم مجمدة، بمواصفات حسب النوع والمنشأ والعيار وطريقة التقديم.","الطازج والمجمد لا يتنافسان، بل يلبّيان احتياجات مختلفة في المطبخ والتوزيع ودوران المخزون. وحسن الاختيار يبدأ بمعرفة الغرض من الشراء."],"link":{"label":"عرض القشريات والرخويات","href":"products/seafood/shellfish/"}},{"id":"zona-fao","tag":"origin","image":"fish","title":"كيف تُقرأ منطقة FAO.","dek":"الرقم المرافق لكل سمكة يدل على مكان صيدها. وهكذا يُفسَّر.","body":["تقسّم منظمة الأغذية والزراعة (FAO) البحار والمحيطات إلى مناطق صيد كبرى مرقّمة. وفي الاتحاد الأوروبي، تُعد منطقة الصيد جزءًا من المعلومات الإلزامية لمنتجات الصيد: فهي أدق طريقة للتعبير عن منشئها.","تظهر في كتالوجنا ثلاث مناطق رئيسية: المنطقة 27، شمال شرق المحيط الأطلسي؛ والمنطقة 34، وسط شرق المحيط الأطلسي؛ والمنطقة 37، البحر الأبيض المتوسط والبحر الأسود، التي تنقسم بدورها إلى مناطق فرعية مثل 37.1.3 أو 37.2.","لذلك نذكر لكل مرجع بلد المنشأ ومنطقة FAO. فهي المعلومات التي تتيح المقارنة والتوثيق والتسويق بشفافية."],"link":{"label":"عرض الأسماك","href":"products/seafood/fish/"}},{"id":"calibre","tag":"product","image":"cephalopods","title":"العيار لا يُقاس بالطريقة نفسها في كل مكان.","dek":"وزن القطعة، أو عدد القطع في الكيلوغرام، أو القطر: لكل فئة مقياسها.","body":["الحديث عن العيار دون تحديد المقياس مصدر شائع لسوء الفهم. ففي الأسماك يُعبَّر عنه عادةً بوزن القطعة؛ وفي القشريات والرخويات بعدد القطع في الكيلوغرام؛ وفي الفاكهة بالقطر أو بعدد القطع في العبوة.","لذلك تتناول كل بطاقة في كتالوجنا العيار وفق فئة المنتج، ووفق مواصفات المشتري عند الاقتضاء.","المواصفات الجيدة — العيار وطريقة التقديم والشكل والتعبئة — نصف الشراء الجيد."],"link":{"label":"عرض المأكولات البحرية","href":"products/seafood/"}},{"id":"referencia-permanente","tag":"company","image":"news","title":"مرجع دائم لكل منتج.","dek":"أربعة أرقام لا تتغير: هكذا يُعرَّف كل منتج في الاستفسارات والطلبيات والعروض.","body":["لكل منتج في الكتالوج — بحريًا كان أو فاكهة أو من الخضروات — مرجعه الخاص المؤلف من أربعة أرقام، والظاهر في بطاقته.","المرجع دائم: لا يتوقف على اللغة ولا على ترتيب الكتالوج ولا على الموسم. ويتيح الإشارة إلى المنتج دون لبس في استفسار أو طلبية أو عرض، بأي من لغاتنا الخمس."],"link":{"label":"عرض جميع المنتجات","href":"products/"}},{"id":"cinco-idiomas","tag":"company","image":"season","title":"كتالوج واحد بخمس لغات.","dek":"الإسبانية والإنجليزية والفرنسية والإيطالية والعربية تتشارك الانتقاء والتصميم والمراجع.","body":["يُقدَّم كتالوج EMPERIO TISS بالإسبانية والإنجليزية والفرنسية والإيطالية والعربية، بالانتقاء نفسه من المنتجات وبالتصميم نفسه للبطاقة.","تُكيَّف الأسماء التجارية مع كل لغة، بينما يبقى الاسم العلمي والمنشأ ومنطقة FAO والمرجع كما هي. وهكذا يتحدث المشترون في الأسواق المختلفة عن المنتج نفسه تمامًا."],"link":{"label":"التواصل مع EMPERIO TISS","href":"contact/"}}],"quote":{"text":"الانتقاء قرار عن بصيرة: أي منتج، ومن أي منشأ، وفي أي وقت.","cite":"EMPERIO TISS"},"letter":{"kicker":"النشرة","h2":"الجوهر،<br><em>في بريدكم.</em>","text":"مستجدات الكتالوج، وملاحظات الموسم، وقراءات في المنتجات. بلا ضجيج: فقط ما يهم من يشتري."}}};
